import{_ as s,o as i,c as e,a4 as t}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse('{"title":"Sharding + Replication 实践","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/scale/sharding-replication.md","filePath":"system-design/scale/sharding-replication.md","lastUpdated":1788475713000}'),n={name:"system-design/scale/sharding-replication.md"};function r(l,a,h,o,d,p){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="sharding-replication-实践" tabindex="-1">Sharding + Replication 实践 <a class="header-anchor" href="#sharding-replication-实践" aria-label="Permalink to &quot;Sharding + Replication 实践&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Scale 的 two axes: <strong>write scalability (sharding)</strong> + <strong>read scalability (replication)</strong>. 本章以 concrete 案例讲解 怎么拆一个单机 Postgres 到 100 节点 cluster:</p><ul><li><strong>Sharding</strong>: 按 hash / range 切 data, 跨多 instances, 让写 throughput 线性增长.</li><li><strong>Replication</strong>: 每个 shard 多副本 (leader + followers) 承载 read traffic, 热备 failover.</li><li><strong>Combined</strong>: CockroachDB / Spanner / Yugabyte / TiDB 是 sharding + replication natively.</li><li><strong>Caching + CDN</strong>: 加 读 cache (Redis + CDN) further 降 read load.</li></ul><p>本章以 Twitter / Instagram 为实例, 讲 shard key 为何是 user_id, 不 <code>hash(ad_id)</code>. 与 pitfalls: reshard migration, 跨 shard transaction, hot shard。</p><hr><h2 id="一、单机到-sharded-集群" tabindex="-1">一、单机到 Sharded 集群 <a class="header-anchor" href="#一、单机到-sharded-集群" aria-label="Permalink to &quot;一、单机到 Sharded 集群&quot;">​</a></h2><h3 id="路径" tabindex="-1">路径 <a class="header-anchor" href="#路径" aria-label="Permalink to &quot;路径&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Phase 1: 单机 Postgres (16 core, 256GB RAM) </span></span>
<span class="line"><span>  → 5000 write TPS, 50K read QPS OK</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Phase 2: + read replicas (1 primary + 2 replicas)</span></span>
<span class="line"><span>  → reads go to replicas, write still bottleneck at primary</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Phase 3: + Redis cache layer</span></span>
<span class="line"><span>  → cache hit 95%, write 仍是瓶颈</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Phase 4: Sharding by user_id (12 shards)</span></span>
<span class="line"><span>  → 写 60K TPS, 读 600K QPS shared across scaling</span></span></code></pre></div><p>Instagram 走完 12 shard, 为什么 user_id 是 shard key:</p><ul><li>Most queries = per-user feed / profile / timeline</li><li>user_id sharding → single-user data co-located on same shard</li><li>Cross-user join (rare) → cross-shard read async 后合并</li></ul><hr><h2 id="二、shard-key-选型-checklist" tabindex="-1">二、Shard Key 选型 checklist <a class="header-anchor" href="#二、shard-key-选型-checklist" aria-label="Permalink to &quot;二、Shard Key 选型 checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>考虑</th><th>Hash 随机分布</th><th>Range 按序分</th><th>Directory 自由映射</th></tr></thead><tbody><tr><td>均匀分布</td><td>✅</td><td>❌ hot range at 最新</td><td>✅ manual rebalance</td></tr><tr><td>范围查询高效</td><td>❌ cross shard</td><td>✅ 同 shard</td><td>✅ depends on mapping</td></tr><tr><td>Hot key</td><td>⚠ single hot key hits one shard</td><td>❌ latest time hits same shard</td><td>✅ manual split hot key</td></tr><tr><td>Add node</td><td>❌ rehash all data (no consistent hash)</td><td>✅ split range 迁移少</td><td>✅ directory 重 map 轻</td></tr><tr><td>Consistent hashing</td><td>✅ 仅 迁移1/N data</td><td>❌ 必须 有 cohesive mechanism</td><td>✅</td></tr></tbody></table><h3 id="实际选型" tabindex="-1">实际选型: <a class="header-anchor" href="#实际选型" aria-label="Permalink to &quot;实际选型:&quot;">​</a></h3><ul><li><strong>Twitter timeline</strong>: <code>user_id % 4096</code> — hash shard, scale via 4K shards.</li><li><strong>HBase region</strong>: range by row key — 时限扫 批量 efficient.</li><li><strong>Vitess</strong>: auto-shard, directory-based (vtgate lookup route).</li></ul><hr><h2 id="三、replication-topology" tabindex="-1">三、Replication / Topology <a class="header-anchor" href="#三、replication-topology" aria-label="Permalink to &quot;三、Replication / Topology&quot;">​</a></h2><h3 id="单主模式-leader-follower" tabindex="-1">单主模式 (leader-follower) <a class="header-anchor" href="#单主模式-leader-follower" aria-label="Permalink to &quot;单主模式 (leader-follower)&quot;">​</a></h3><p>单 shard 内 leader + 2+ followers。 leader 承载 write, followers 承载 reads.</p><ul><li>若 leader down → Raft/Paxos elect new leader (5-10s).</li><li>RPO = ack to client after fsync+半数. replication lag reads maybe stale.</li></ul><h3 id="多主多-region" tabindex="-1">多主多 region <a class="header-anchor" href="#多主多-region" aria-label="Permalink to &quot;多主多 region&quot;">​</a></h3><p>CockroachDB <strong>multi-region 表</strong>:</p><ul><li><code>PRIMARY REGION &quot;us-east&quot;</code> all table 在 该区域</li><li><code>REGIONAL BY ROW</code>: each row across regions based region key</li><li><code>GLOBAL</code> 表: table 跨 all regions 一致 replicas</li></ul><h3 id="链式复制-chain-replication" tabindex="-1">链式复制 Chain Replication <a class="header-anchor" href="#链式复制-chain-replication" aria-label="Permalink to &quot;链式复制 Chain Replication&quot;">​</a></h3><p>Head → middle → tail (写入顺序, 仅 tail 可读). 低 latency reads, 单 tail throughput bottleneck. 用于 strong consistency read 线.</p><hr><h2 id="四、跨-shard-transaction" tabindex="-1">四、跨 shard transaction <a class="header-anchor" href="#四、跨-shard-transaction" aria-label="Permalink to &quot;四、跨 shard transaction&quot;">​</a></h2><h3 id="_2pc-via-xa-2-phase-commit" tabindex="-1">2PC via XA (2 Phase Commit) <a class="header-anchor" href="#_2pc-via-xa-2-phase-commit" aria-label="Permalink to &quot;2PC via XA (2 Phase Commit)&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XA </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">START</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;tx1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> accounts_1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> accounts_2 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 99</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XA </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">END</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;tx1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XA PREPARE </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;tx1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XA </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COMMIT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;tx1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Pros: Strict ACID; Cons: latency ~10-50ms, 2PC 阻塞 coordinator 崩 死锁。</p><h3 id="saga-pattern" tabindex="-1">Saga Pattern <a class="header-anchor" href="#saga-pattern" aria-label="Permalink to &quot;Saga Pattern&quot;">​</a></h3><p>每个 shard update is local transaction + 补偿 undo event.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service A deduct (shard 1). commit event.</span></span>
<span class="line"><span>Service B add (shard 2). commit event ∈ kafka.</span></span>
<span class="line"><span>if B fails, emit compensation event to A.</span></span></code></pre></div><h3 id="cockroachdb-cross-shard-serializability" tabindex="-1">CockroachDB cross-shard serializability <a class="header-anchor" href="#cockroachdb-cross-shard-serializability" aria-label="Permalink to &quot;CockroachDB cross-shard serializability&quot;">​</a></h3><p>HLC + Paxos replication + 2PC (internally impl), 应用不用手写 2PC; ~80ms serially.</p><hr><h2 id="五、reshard-rebalance" tabindex="-1">五、Reshard / Rebalance <a class="header-anchor" href="#五、reshard-rebalance" aria-label="Permalink to &quot;五、Reshard / Rebalance&quot;">​</a></h2><h3 id="hash-based-with-consistent-hashing" tabindex="-1">Hash-Based With Consistent Hashing <a class="header-anchor" href="#hash-based-with-consistent-hashing" aria-label="Permalink to &quot;Hash-Based With Consistent Hashing&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>consistent hashing ring + virtual nodes (150 vnodes per node per Riak).</span></span>
<span class="line"><span>add node → move ~1/N data.</span></span></code></pre></div><h3 id="range-split" tabindex="-1">Range Split <a class="header-anchor" href="#range-split" aria-label="Permalink to &quot;Range Split&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Shard starts [0, MAX]; 当 shard 负载 &gt; threshold → split.</span></span>
<span class="line"><span>new shard hot until cache prewarm.</span></span></code></pre></div><h3 id="vitess-vreplication" tabindex="-1">Vitess VReplication <a class="header-anchor" href="#vitess-vreplication" aria-label="Permalink to &quot;Vitess VReplication&quot;">​</a></h3><ol><li>vreplicate双写 + binlog capture.</li><li>等到 slave caught up → 切新 shard 全读.</li><li>remove old shard.</li></ol><hr><h2 id="六、典型事故" tabindex="-1">六、典型事故 <a class="header-anchor" href="#六、典型事故" aria-label="Permalink to &quot;六、典型事故&quot;">​</a></h2><h3 id="instagram-2014-reshard" tabindex="-1">Instagram 2014 reshard <a class="header-anchor" href="#instagram-2014-reshard" aria-label="Permalink to &quot;Instagram 2014 reshard&quot;">​</a></h3><p>Originally 12-postgres shard by user_id % 4096. 随着 user 增长, 单 shard 接近 max capacity. Upgrade 12→24 requires a massive data migration; Instagram did it via logical replication + 临时读写两 方案。 migration took 6 months planning.</p><h3 id="uber-schemaless-holodeck-sharding" tabindex="-1">Uber Schemaless / Holodeck Sharding <a class="header-anchor" href="#uber-schemaless-holodeck-sharding" aria-label="Permalink to &quot;Uber Schemaless / Holodeck Sharding&quot;">​</a></h3><p>Uber 的 early 阶段 used hash sharding 后 由于 shard 数少 hot shard 叠加 让 drivers available 数写 慢。 created custom shard: partitioned by <code>city_id + user_id</code> 双 层 shard.</p><h3 id="figma-no-sharding-at-all" tabindex="-1">Figma: no sharding at all <a class="header-anchor" href="#figma-no-sharding-at-all" aria-label="Permalink to &quot;Figma: no sharding at all&quot;">​</a></h3><p>Figma uses single PostgreSQL instance (2021 blog) for up to 1B+ objects, relying heavily on Nginx + Redis cache + heavy horizontal read replicas. Write stayed moderate because most user actions generate <strong>local state</strong> that 未 persist each micro gesture.</p><hr><h2 id="七、易错清单" tabindex="-1">七、易错清单 <a class="header-anchor" href="#七、易错清单" aria-label="Permalink to &quot;七、易错清单&quot;">​</a></h2><ol><li><strong>Shard key 选择 必 基于 query pattern</strong>: 不能随便 <code>hash(random)</code> — 以后 查 单 user 跨 shard 太贵.</li><li><strong>Reshard 的 migrate cost 巨大</strong>: plan for &quot;scale 2-4× what you need now&quot; to avoid immediate migration.</li><li><strong>Cross-shard transaction is hard: 2PC 才 linearizable, Saga eventual, eventual 是 path correct 但 业务 onus 大</strong>.</li><li><strong>Read replica can become stale and cause user to see old data</strong>: 控制 replication lag; read-after-write consistency 必须.</li></ol><hr><h2 id="八、这一章带走的东西" tabindex="-1">八、这一章带走的东西 <a class="header-anchor" href="#八、这一章带走的东西" aria-label="Permalink to &quot;八、这一章带走的东西&quot;">​</a></h2><ol><li>Sharding = hash / range / directory; 选 key 基于 query pattern.</li><li>Replication = leader-follower (单主) / 链 / 多主多 region.</li><li>Cross-shard tx = 2PC (ACID) vs Saga (eventual), trade latency and consistency.</li><li>Reshard with consistent hashing (move 1/N data) or range split (less data move).</li><li>Instagram / Uber / Figma patterns confirm shard design dictated by product use-cases.</li></ol><hr><p>下一节 → <a href="./multi-region">Multi-region</a></p>`,60)])])}const k=s(n,[["render",r]]);export{g as __pageData,k as default};
